function drape(ctx, seed, strength){
  const c=document.createElement('canvas'); c.width=W; c.height=H
  const g=c.getContext('2d')
  const img=g.createImageData(W,H)
  // the fold phase advances across the plate and wanders slowly down it
  const wander = noiseField(W,H,W*0.9,seed)      // where the folds lean
  const width  = noiseField(W,H,W*0.55,seed+1)   // how wide each fold is
  const creaseN= noiseField(W,H,W*0.08,seed+2)   // small rumples on the surface
  const foldW = 150 + 110*((seed%7)/7)
  for(let y=0;y<H;y++){
    for(let x=0;x<W;x++){
      const lean = (wander(x*0.25, y)-0.5)*260
      const w = foldW*(0.75+width(x,y*0.6)*0.6)
      const ph = (x + lean)/w
      const t = Math.cos(ph*Math.PI*2)*0.5+0.5          // 1 on the ridge, 0 in the crease
      // ridges broad and softly lit, creases narrow and dark
      let lum = 0.34 + 0.72*Math.pow(t,0.62)
      // the crease itself gets a thin dark core
      lum -= 0.22*Math.pow(1-t, 6)
      // slow rumple across the surface, and a fall-off towards the plate edges
      lum *= 0.90 + 0.20*creaseN(x,y)
      const edge = Math.min(1, Math.min(x, W-x)/(W*0.22))
      lum *= 0.86 + 0.14*edge
      lum *= 1.02 - 0.14*(y/H)
      lum = 0.5 + (lum-0.5)*strength*1.55
      const o=(y*W+x)*4
      const l = Math.max(0,Math.min(255, lum*255*2))
      img.data[o]=img.data[o+1]=img.data[o+2]=l; img.data[o+3]=255
    }
  }
  g.putImageData(img,0,0)
  ctx.globalCompositeOperation='multiply'; ctx.globalAlpha=0.92; ctx.drawImage(c,0,0)
  ctx.globalCompositeOperation='screen';   ctx.globalAlpha=0.22; ctx.drawImage(c,0,0)
  ctx.globalCompositeOperation='source-over'; ctx.globalAlpha=1
}

\`;
fs.writeFileSync('tools/weave.html', s.slice(0,start)+nu+s.slice(end));
console.log('ok')"

