const rowH = gauge*0.72
const cols = Math.ceil(W/gauge)+3, rows = Math.ceil(H/rowH)+3
ctx.fillStyle = shade(o.warp[0],0.42); ctx.fillRect(0,0,W,H)
ctx.lineCap='round'; ctx.lineJoin='round'
const n = noiseField(W,H,gauge*8,o.seed+3)

// one stitch: the loop drawn as a tube, lit from the top-left, sitting over
// the row below it so the courses interlock instead of forming a mesh
function stitch(x,y,col,lift){
  const w = gauge, h = rowH
  for(const dir of [-1,1]){
    const x0 = x+w*0.5, y0 = y+h*1.06
    const x1 = x+w*0.5+dir*w*0.30, y1 = y+h*0.52
    const x2 = x+w*0.5+dir*w*0.50, y2 = y-h*0.30
    // shadow under the leg, which is what makes the course read as raised
    ctx.strokeStyle = shade(col, 0.52*lift); ctx.lineWidth = w*0.50
    ctx.beginPath(); ctx.moveTo(x0,y0+h*0.10)
    ctx.quadraticCurveTo(x1,y1+h*0.10,x2,y2+h*0.10); ctx.stroke()
    // the yarn itself
    ctx.strokeStyle = shade(col, (dir<0?0.86:1.02)*lift); ctx.lineWidth = w*0.42
    ctx.beginPath(); ctx.moveTo(x0,y0); ctx.quadraticCurveTo(x1,y1,x2,y2); ctx.stroke()
    // crown highlight, offset towards the light
    ctx.strokeStyle = shade(col, 1.30*lift); ctx.lineWidth = w*0.11
    ctx.beginPath(); ctx.moveTo(x0-w*0.03,y0-h*0.04)
    ctx.quadraticCurveTo(x1-w*0.04,y1-h*0.05,x2-w*0.04,y2-h*0.05); ctx.stroke()
  }
}

for(let j=0;j<rows;j++){
  const y=j*rowH - rowH
  const off = (j%2)? gauge*0.5 : 0
  for(let i=-1;i<cols;i++){
    const x=i*gauge+off
    const col = o.warp[Math.floor(r()*o.warp.length)]
    stitch(x, y, col, 0.86 + n(x,y)*0.26)
  }
}

