@font-face {
  font-family: 'Instrument Serif';
  src: url('/type/instrument-serif.woff2') format('woff2');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Instrument Serif';
  src: url('/type/instrument-serif-italic.woff2') format('woff2');
  font-weight: 400; font-style: italic; font-display: swap;
}
@font-face {
  font-family: 'Inter';
  src: url('/type/inter.woff2') format('woff2');
  font-weight: 100 900; font-style: normal; font-display: swap;
}

:root {
  --ink: #ece5d6;
  --ink-dim: #9d958a;
  --ground: #17150f;
  --ground-2: #0f0e0a;
  --rule: rgba(236, 229, 214, 0.22);
  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --pad: clamp(14px, 2.4vw, 34px);
}

* { box-sizing: border-box; }

html { background: var(--ground-2); }

body {
  margin: 0;
  background: var(--ground-2);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ---------------------------------------------------------------- the scene */

.scene { height: 420vh; position: relative; }

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% 0%, #211d14 0%, var(--ground) 55%, var(--ground-2) 100%);
}

/* the window itself: a cut in the page, with the cloth running behind it */
.board {
  position: absolute;
  left: var(--pad);
  right: var(--pad);
  top: clamp(96px, 15vh, 150px);
  bottom: clamp(52px, 8vh, 84px);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: clamp(6px, 0.85vw, 13px);
}

.card {
  --s: 0;
  position: relative;
  transform-origin: 0 0;
  will-change: transform;
  overflow: hidden;
  background: #100f0b;
  box-shadow:
    0 0 0 1px rgba(236, 229, 214, calc(0.05 + 0.13 * var(--s))),
    0 calc(16px * var(--s)) calc(44px * var(--s)) rgba(0, 0, 0, 0.5);
}

.card-window {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.scaler { position: absolute; top: 0; left: 0; transform-origin: 0 0; }

.sheet {
  display: block;
  max-width: none;
  transform-origin: 0 0;
  will-change: transform;
  user-select: none;
  -webkit-user-drag: none;
}

/* the card's own reading, which only exists once it has its own frame */
.card-face {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  padding: clamp(10px, 1.1vw, 18px);
  opacity: calc((var(--s) - 0.72) * 3.6);
  transform: translateY(calc((1 - var(--s)) * 12px));
  background: linear-gradient(to top, rgba(11, 10, 7, 0.88), rgba(11, 10, 7, 0.4) 46%, transparent);
  pointer-events: none;
}

.card-name {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(17px, 1.5vw, 25px);
  letter-spacing: 0.01em;
  line-height: 1.05;
}

.card-meta {
  margin: 5px 0 0;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: clamp(10px, 0.72vw, 12px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

/* ------------------------------------------------------------ the overlays */

.mast {
  position: absolute;
  left: var(--pad);
  right: var(--pad);
  top: clamp(22px, 3.6vh, 44px);
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  z-index: 3;
  mix-blend-mode: normal;
}

.mast-name {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(30px, 4.4vw, 68px);
  line-height: 0.9;
  letter-spacing: -0.015em;
  transform: translateY(calc(var(--split, 0) * -14px));
}

.mast-line {
  margin: 0;
  max-width: 30ch;
  text-align: right;
  font-size: clamp(11px, 0.82vw, 13px);
  line-height: 1.45;
  color: var(--ink-dim);
  opacity: calc(1 - var(--split, 0) * 1.4);
}

/* the running caption: what is in the window at this instant */
.reading {
  position: absolute;
  left: var(--pad);
  bottom: clamp(52px, 8vh, 84px);
  padding: 14px 18px 13px;
  z-index: 3;
  display: grid;
  gap: 2px;
  background: rgba(9, 8, 6, 0.62);
  backdrop-filter: blur(7px);
  border-left: 1px solid var(--rule);
  opacity: calc(1 - var(--split, 0) * 1.8);
  transform: translateY(calc(var(--split, 0) * 18px));
}

.reading-index {
  margin: 0;
  font-family: var(--serif);
  font-size: 26px;
  line-height: 1;
}
.reading-index span { font-size: 13px; color: var(--ink-dim); }

.reading-cloth {
  margin: 4px 0 0;
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.reading-note { margin: 0; font-size: 12px; color: var(--ink-dim); }

.selvedge {
  position: absolute;
  left: var(--pad);
  right: var(--pad);
  bottom: clamp(18px, 2.6vh, 30px);
  margin: 0;
  font-size: 11px;
  line-height: 1.4;
  letter-spacing: 0.02em;
  color: var(--ink-dim);
  z-index: 3;
  max-width: 62ch;
}

.after {
  min-height: 60vh;
  display: grid;
  place-items: center;
  background: var(--ground-2);
  color: var(--ink-dim);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* ---------------------------------------------------------------- narrow */

@media (max-width: 760px) {
  .board {
    top: clamp(104px, 17vh, 170px);
    bottom: clamp(64px, 9vh, 90px);
    grid-template-columns: 1fr;
    grid-template-rows: repeat(9, 1fr);
    gap: 4px;
  }
  .card-face {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 11px;
  }
  .card-name { font-size: 17px; }
  .card-meta { margin: 0; }
  .card-meta span:first-child { display: none; }
  .mast { flex-direction: column; gap: 6px; }
  .mast-line { text-align: left; max-width: 34ch; }
  .reading { padding: 9px 13px; }
  .reading-index { font-size: 20px; }
  .selvedge { font-size: 10px; }
}

/* ------------------------------------------------------- reduced motion */

@media (prefers-reduced-motion: reduce) {
  .scene { height: auto; }
  .stage { position: static; height: 100vh; }
  .card { --s: 1; }
