  const h=document.querySelector('.scene').offsetHeight - window.innerHeight;
  window.scrollTo(0,h*0.55);
  await new Promise(r=>setTimeout(r,200));
  // drive a scrub and measure frame intervals
  const times=[]; let last=performance.now(); let y=h*0.55; let raf;
  await new Promise(res=>{
    let n=0;
    const step=(t)=>{ times.push(t-last); last=t; y+=14; window.scrollTo(0,y); if(++n<120) raf=requestAnimationFrame(step); else res() };
    raf=requestAnimationFrame(step);
  });
  times.sort((a,b)=>a-b);
  return {median: +times[60].toFixed(2), p90: +times[108].toFixed(2), max:+times[119].toFixed(2)};
}

