}
.bagwrap.is-open .bagpanel { transform: none; }

.bag-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; }
.bag-head h2 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 30px; }

.bag-close, .bag-remove {
  border: 0;
  background: transparent;
  color: var(--ink-dim);
  font: inherit;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  padding: 6px 2px;
  transition: color 0.2s var(--ease);
}
.bag-close:hover, .bag-remove:hover { color: var(--accent); }

.bag-empty { margin: 0; color: var(--ink-dim); font-size: 14px; }

.bag-lines { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }
.bag-line {
  display: grid;
  grid-template-columns: 52px 1fr auto;
  align-items: center;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(236, 229, 214, 0.12);
}
.plate.is-chip { aspect-ratio: 1 / 1; }
.bag-line-body { display: grid; gap: 3px; }
.bag-line-name { margin: 0; font-family: var(--serif); font-size: 18px; line-height: 1.1; }
.bag-line-meta { margin: 0; font-size: 12px; color: var(--ink-dim); }

.bag-sums { display: grid; gap: 7px; font-size: 14px; }
.bag-sums p { margin: 0; display: flex; justify-content: space-between; gap: 12px; }
.bag-gap { color: var(--accent); font-size: 12.5px; display: block !important; }
.bag-total {
  padding-top: 10px;
  border-top: 1px solid rgba(236, 229, 214, 0.2);
  font-size: 17px;
}

.bag-checkout {
  padding: 15px;
  border: 0;
  background: var(--ink);
  color: var(--ground-2);
  font: inherit;
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.22s var(--ease), transform 0.1s var(--ease);
}
.bag-checkout:hover { background: var(--accent); color: #fff; }
.bag-checkout:active { transform: translateY(1px); }

.bag-foot { margin: 0; font-size: 11.5px; line-height: 1.5; color: var(--ink-dim); }

/* --------------------------------------------------------------- narrow */

@media (max-width: 900px) {
  .pane { grid-template-columns: 1fr; }
  .house { grid-template-columns: 1fr; }
  .house-plate .plate.is-wide { aspect-ratio: 16 / 9; }
}

@media (max-width: 760px) {
  .bar-nav { display: none; }
  .bar-bag { margin-left: auto; }
  .rail { grid-template-columns: 1fr; }
  .bagpanel { top: auto; height: min(86vh, 700px); width: 100%; border-left: 0; border-top: 1px solid rgba(236, 229, 214, 0.16); transform: translateY(101%); }
  .bagwrap.is-open .bagpanel { transform: none; }
  .size { min-width: 52px; padding: 13px 8px; }
  .chart { font-size: 14px; }
  .chart th, .chart td { padding: 11px 6px; }
}

/* ------------------------------------------------------- reduced motion */

@media (prefers-reduced-motion: reduce) {
  .bar { transition: none; }
  .skip { transition: none; }
  [data-reveal] { opacity: 1; transform: none; transition: none; }
  .good:hover { transform: none; }
  .bagpanel, .bag-scrim { transition: none; }
  .plate-img { transform: translate3d(calc(var(--i) * -11.1111%), -6%, 0); }
  * { scroll-behavior: auto !important; }
}
